def choose_move(observation):
    # Defensive extraction of common fields
    grid = observation.get('grid', [])
    role = observation.get('role')
    position = observation.get('position', (0, 0))
    height = observation.get('height', 0)
    width = observation.get('width', 0)

    # Helper to find positions of particular entities
    def find_positions(entity_type):
        positions = []
        for y in range(height):
            for x in range(width):
                if grid and grid[y][x] == entity_type:
                    positions.append((x, y))
        return positions

    # Determine if resources are available
    resources = find_positions('resource') if 'resource' in role or 'resource' in observation.get('resources', []) else []
    enemies = find_positions('enemy') if 'enemy' in role or 'enemy' in observation.get('enemies', []) else []

    # Map for neighbor positions
    directions = [(-1,0),(1,0),(0,-1),(0,1)]
    x, y = position

    # Utility: get content at position
    def content_at(pos):
        px, py = pos
        if 0 <= px < width and 0 <= py < height:
            return grid[py][px]
        return None

    # Priority:
    # 1. If resource available, move towards nearest resource.
    # 2. If enemy nearby, pursue or evade based on role.
    # 3. Else, move arbitrarily or towards center.

    # Find nearest resource
    if resources:
        def dist(p):
            return abs(p[0]-x)+abs(p[1]-y)
        resource_pos = min(resources, key=dist)
        dx = dy = 0
        if resource_pos[0] > x:
            dx = 1
        elif resource_pos[0] < x:
            dx = -1
        elif resource_pos[1] > y:
            dy = 1
        elif resource_pos[1] < y:
            dy = -1
        if content_at((x+dx, y+dy)) in (None, 'resource'):
            return [dx, dy]

    # If no resource, look for enemies
    for ex, ey in enemies:
        dist_en = abs(ex - x) + abs(ey - y)
        if dist_en == 1:
            # Enemy adjacent
            if role == 'pursuer':
                # Pursue enemy
                dx = 0
                dy = 0
                if ex > x:
                    dx = 1
                elif ex < x:
                    dx = -1
                if ey > y:
                    dy = 1
                elif ey < y:
                    dy = -1
                if content_at((x+dx, y+dy)) != 'obstacle':
                    return [dx, dy]
            elif role == 'evader':
                # Evade enemy
                dx = 0
                dy = 0
                if ex > x:
                    dx = -1
                elif ex < x:
                    dx = 1
                if ey > y:
                    dy = -1
                elif ey < y:
                    dy = 1
                if content_at((x+dx, y+dy)) != 'obstacle':
                    return [dx, dy]
    # Else, move towards center to explore
    center_x, center_y = width // 2, height // 2
    dx = 0
    dy = 0
    if center_x > x:
        dx = 1
    elif center_x < x:
        dx = -1
    if center_y > y:
        dy = 1
    elif center_y < y:
        dy = -1
    # Check move validity
    if content_at((x+dx, y+dy)) in (None, 'resource'):
        return [dx, dy]
    # Else, explore in a safe direction
    for ndx, ndy in directions:
        nx, ny = x + ndx, y + ndy
        if 0 <= nx < width and 0 <= ny < height:
            if content_at((nx, ny)) in (None, 'resource'):
                return [ndx, ndy]
    # Default stay in place
    return [0, 0]
